// Trace emitter: spans nest, attributes attach (plain JS pattern)
function makeTracer() {
  const spans = [];
  return {
    span(name, parent = null) {
      const s = { name, parent, t0: Date.now(), attrs: {} };
      spans.push(s);
      return {
        set: (k, v) => (s.attrs[k] = v),
        end: (status = "ok") => { s.ms = Date.now() - s.t0; s.status = status; },
      };
    },
    report: () => spans.map((s) => ({ name: s.name, ms: s.ms, status: s.status, ...s.attrs })),
  };
}
// Boundaries emit spans: router decisions, tool calls, citation counts, token use.

