const ALERTS = [
  { signal: "overrideRate", when: (v, b) => v > b * 1.5, runbook: "quality-drop", owner: "agent-team" },
  { signal: "costPerTask", when: (v, b) => v > b * 2, runbook: "cost-spike", owner: "platform" },
  { signal: "abstentionRate", when: (v, b) => v > b * 2, runbook: "corpus-gap", owner: "data-team" },
  { signal: "p99", when: (v, b) => v > b * 1.5, runbook: "tail-hunt", owner: "agent-team" },
  { signal: "refusalSpike", when: (v, b) => v > b * 3, runbook: "campaign-check", owner: "security" },
];
// Relative thresholds (× baseline) adapt to growth; absolutes rot within quarters.

